// Probe (sonde) — one red case per suspected defect, run against today's code.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  step, createState, makeBricks, collides,
  WIDTH, HEIGHT, PADDLE_Y, PADDLE_H, PADDLE_W, BALL_R,
  BRICK_COLS,
} from '../game/neon.js';

const DOWN = 1;
const UP = -1;
const LEFT = -1;
const RIGHT = 1;

const brickAt = (state, row, col) => state.bricks[row * BRICK_COLS + col];

// D1 — no bounce on brick hit (head-on bottom-face hit, level 1, dt=1/60)
test('D1: ball bouncing off the bottom face of a brick ends outside, moving down', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 3); // row 0, col 3: x 244..316, y 48..68
  state.bricks.forEach((b) => { if (b !== brick) b.alive = false; });
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + BALL_R + 4, r: BALL_R, vx: 0, vy: -ballSpeed1() };
  step(state, 1 / 60); // travel 4.33px → top edge 0.33px inside the brick
  assert.equal(brick.alive, false, 'the hit brick must die');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'ball must come back down');
  assert.ok(state.ball.y + state.ball.r <= brick.y + brick.h + 1e-6, 'ball must be outside, below the brick');
  assert.equal(collides(state.ball, brick), false, 'no residual overlap');
});
function ballSpeed1() { return 260; }

// D2 — side hit must flip vx, not vy
test('D2: side hit flips vx and leaves vy untouched, ball pushed out sideways', () => {
  const state = createState(1);
  const brick = brickAt(state, 1, 1); // row 1, col 1: x 84..156, y 76..96
  state.bricks.forEach((b) => { if (b !== brick) b.alive = false; });
  state.ball = { x: brick.x - 8, y: brick.y + 10, r: BALL_R, vx: 260, vy: 0 };
  step(state, 0.02); // travel 5.2px → right edge 4.2px inside the brick
  assert.equal(brick.alive, false, 'the hit brick must die');
  assert.equal(Math.sign(state.ball.vx), LEFT, 'horizontal velocity must flip to the left');
  assert.equal(state.ball.vy, 0, 'vertical velocity must be untouched');
  assert.ok(state.ball.x + state.ball.r <= brick.x + 1e-6, 'ball must be pushed out to the left of the brick');
  assert.equal(collides(state.ball, brick), false);
});

// D2 corner — equal penetration on both axes → both velocities flip
test('D2: corner hit (equal penetration) flips both vx and vy', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 1); // row 0, col 1: x 84..156, y 48..68
  state.bricks.forEach((b) => { if (b !== brick) b.alive = false; });
  state.ball = { x: brick.x - 7.6, y: brick.y - 7.6, r: BALL_R, vx: 260, vy: 260 };
  step(state, 0.01); // travel 2.6px each axis → penetration 2px on both axes
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx must flip on a corner hit');
  assert.equal(Math.sign(state.ball.vy), UP, 'vy must flip on a corner hit');
  assert.equal(collides(state.ball, brick), false);
});

// D3 — push-out: after resolution the ball must be out of the brick (no collant)
test('D3: after a top-face bounce the ball is pushed outside the brick', () => {
  const state = createState(1);
  const brick = brickAt(state, 2, 3); // row 2, col 3: x 244..316, y 104..124
  state.bricks.forEach((b) => { if (b !== brick) b.alive = false; });
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.05); // travel 13px → center 12px inside the brick
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'ball must bounce upward off the top face');
  assert.ok(state.ball.y + state.ball.r <= brick.y + 1e-6, 'ball must end above the brick, not inside it');
  assert.equal(collides(state.ball, brick), false, 'no residual overlap after resolution');
});

// D4 — seam / double inversion: one bounce per pass, earliest contact wins
test('D4: a ball crossing the seam between two live rows bounces exactly once', () => {
  const state = createState(5); // speed 620 → step 31px at dt=0.05
  const b1 = brickAt(state, 1, 3); // row 1: y 76..96
  const b2 = brickAt(state, 2, 3); // row 2: y 104..124
  state.bricks.forEach((b) => { if (b.row >= 3) b.alive = false; }); // clear the rows below
  state.ball = { x: b2.x + b2.w / 2, y: 132.5, r: BALL_R, vx: 0, vy: -620 };
  step(state, 0.05); // ends at y=101.5, inside the (97..103) band overlapping BOTH rows
  assert.equal(b2.alive, false, 'the first-contacted brick (row 2) must die');
  assert.equal(b1.alive, true, 'the row above must NOT be touched in the same pass');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'exactly one vertical bounce: ball must be moving down');
  assert.ok(Math.abs(state.ball.y - (b2.y + b2.h + BALL_R)) <= 0.01, 'ball must stop at the contact face');
});

// D5 — tunneling through a brick at high speed (level ≥ 6, dt=50ms)
test('D5: a 35.5px step must not tunnel through a 34px-thick brick', () => {
  const state = createState(6); // speed 710 → step 35.5px > 34px (brick h 20 + ball diameter 14)
  const brick = brickAt(state, 2, 3);
  state.bricks.forEach((b) => { if (b !== brick) b.alive = false; });
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + BALL_R + 0.75, r: BALL_R, vx: 0, vy: -710 };
  step(state, 0.05); // no overlap at either endpoint: y 131.75 → 96.25, fully above the brick
  assert.equal(brick.alive, false, 'the brick on the swept path must be hit');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'the ball must bounce off the bottom face');
  assert.ok(Math.abs(state.ball.y - (brick.y + brick.h + BALL_R)) <= 0.01, 'ball must stop at the contact face');
  assert.equal(collides(state.ball, brick), false);
});

// D6 — paddle tunneling: a 13px step > 12px paddle height at level 1, dt=50ms
test('D6: a ball crossing the paddle in one 13px step must bounce out through the top', () => {
  const state = createState(1);
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  const lost = step(state, 0.05); // bottom goes 447.5 → 460.5, past paddle bottom 460
  assert.equal(lost, false, 'the ball must not be lost');
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball must bounce upward');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y + 1e-6, 'the ball must exit through the top of the paddle');
});

test('D6b: a ball that has NOT reached the paddle yet must not bounce (no ghost bounce)', () => {
  const state = createState(1);
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 13.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.05); // bottom goes 434 → 447, still above the paddle top 448
  assert.equal(Math.sign(state.ball.vy), DOWN, 'no contact yet: the ball keeps descending');
});

// D7 — dead angle: center hit must not give vx = 0
test('D7: a center hit on the paddle keeps a playable exit angle and the level speed', () => {
  const state = createState(1);
  const centerX = state.paddle.x + state.paddle.w / 2;
  state.ball = { x: centerX, y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.01); // bottom 447.5 → 450.1, inside the paddle zone
  assert.equal(Math.sign(state.ball.vy), UP, 'ball must bounce up');
  assert.ok(Math.abs(state.ball.vx) >= 0.15 * 260, `vx must not be zero at the exact center (got ${state.ball.vx})`);
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - 260) <= 1e-6, 'speed after the bounce must be the level speed');
});

// D8 — speed: the paddle bounce must preserve the level speed
test('D8: an edge hit on the paddle preserves the level speed (no speed-up)', () => {
  const state = createState(1);
  const centerX = state.paddle.x + state.paddle.w / 2;
  state.ball = { x: centerX + 0.8 * (state.paddle.w / 2), y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.01); // hit = 0.8
  assert.equal(Math.sign(state.ball.vy), UP);
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - 260) <= 1e-6,
    `speed must be 260 after the paddle bounce (got ${Math.hypot(state.ball.vx, state.ball.vy).toFixed(2)})`);
});

