// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  BALL_R,
  PADDLE_Y,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick collision (issue #1: the ball used to plow straight through) ----

const UP = -1;
const DOWN = 1;
const LEFT = -1;
const RIGHT = 1;

// Picks the brick at (row, col) of the level grid.
function brickAt(state, row, col) {
  return state.bricks[row * BRICK_COLS + col];
}

// Keeps a single brick alive, isolates a scenario from the rest of the grid.
function only(brick, state) {
  state.bricks.forEach((b) => {
    if (b !== brick) b.alive = false;
  });
  return brick;
}

test('D1: ball bouncing off the bottom face of a brick ends outside, moving down', () => {
  const state = createState(1);
  const brick = only(brickAt(state, 0, 3), state); // x 244..316, y 48..68
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + BALL_R + 4,
    r: BALL_R,
    vx: 0,
    vy: -260,
  };
  step(state, 1 / 60); // 4.33px step: the ball ends 0.33px inside the brick
  assert.equal(brick.alive, false, 'the hit brick must die');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'the ball must come back down');
  assert.ok(
    state.ball.y - state.ball.r >= brick.y + brick.h - 1e-6,
    'the ball must be outside, below the brick',
  );
  assert.equal(collides(state.ball, brick), false, 'no residual overlap');
});

test('D2: side hit flips vx and leaves vy untouched, ball pushed out sideways', () => {
  const state = createState(1);
  const brick = only(brickAt(state, 1, 1), state); // x 84..156, y 76..96
  state.ball = { x: brick.x - 8, y: brick.y + 10, r: BALL_R, vx: 260, vy: 0 };
  step(state, 0.02); // 5.2px step: right edge ends 4.2px inside the brick
  assert.equal(brick.alive, false, 'the hit brick must die');
  assert.equal(Math.sign(state.ball.vx), LEFT, 'horizontal velocity must flip to the left');
  assert.equal(state.ball.vy, 0, 'vertical velocity must be untouched');
  assert.ok(
    state.ball.x + state.ball.r <= brick.x + 1e-6,
    'the ball must be pushed out to the left of the brick',
  );
  assert.equal(collides(state.ball, brick), false);
});

test('D2: corner hit (equal penetration) flips both vx and vy', () => {
  const state = createState(1);
  const brick = only(brickAt(state, 0, 1), state); // x 84..156, y 48..68
  state.ball = { x: brick.x - 7.6, y: brick.y - 7.6, r: BALL_R, vx: 260, vy: 260 };
  step(state, 0.01); // 2.6px step: 2px penetration on both axes, a corner
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx must flip on a corner hit');
  assert.equal(Math.sign(state.ball.vy), UP, 'vy must flip on a corner hit');
  assert.equal(collides(state.ball, brick), false);
});

test('D3: after a top-face bounce the ball is pushed outside the brick', () => {
  const state = createState(1);
  const brick = only(brickAt(state, 2, 3), state); // x 244..316, y 104..124
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - BALL_R - 1,
    r: BALL_R,
    vx: 0,
    vy: 260,
  };
  step(state, 0.05); // 13px step: center ends 12px inside the brick
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball must bounce upward off the top face');
  assert.ok(
    state.ball.y + state.ball.r <= brick.y + 1e-6,
    'the ball must end above the brick, not inside it',
  );
  assert.equal(collides(state.ball, brick), false, 'no residual overlap after resolution');
});

test('D4: a ball crossing the seam between two live rows bounces exactly once', () => {
  const state = createState(5); // speed 620 → 31px step at dt=0.05
  const b1 = brickAt(state, 1, 3); // row 1: y 76..96
  const b2 = brickAt(state, 2, 3); // row 2: y 104..124
  state.bricks.forEach((b) => {
    if (b.row >= 3) b.alive = false; // clear the rows below
  });
  state.ball = { x: b2.x + b2.w / 2, y: 132.5, r: BALL_R, vx: 0, vy: -620 };
  step(state, 0.05); // ends at y=101.5, inside the (97..103) band overlapping both rows
  assert.equal(b2.alive, false, 'the first-contacted brick (row 2) must die');
  assert.equal(b1.alive, true, 'the row above must NOT be touched in the same pass');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'exactly one vertical bounce: the ball goes down');
  assert.ok(
    Math.abs(state.ball.y - (b2.y + b2.h + BALL_R)) <= 0.01,
    'the ball must stop at the contact face',
  );
});

test('D5: a 35.5px step must not tunnel through a 34px-thick brick', () => {
  const state = createState(6); // speed 710 → 35.5px step > 34px (brick h 20 + ball diameter 14)
  const brick = only(brickAt(state, 2, 3), state);
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + BALL_R + 0.75,
    r: BALL_R,
    vx: 0,
    vy: -710,
  };
  step(state, 0.05); // no overlap at either endpoint: y 131.75 → 96.25, fully above the brick
  assert.equal(brick.alive, false, 'the brick on the swept path must be hit');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'the ball must bounce off the bottom face');
  assert.ok(
    Math.abs(state.ball.y - (brick.y + brick.h + BALL_R)) <= 0.01,
    'the ball must stop at the contact face',
  );
  assert.equal(collides(state.ball, brick), false);
});

test('D6: a ball crossing the paddle in one 13px step must bounce out through the top', () => {
  const state = createState(1);
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  const lost = step(state, 0.05); // bottom goes 447.5 → 460.5, past paddle bottom 460
  assert.equal(lost, false, 'the ball must not be lost');
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball must bounce upward');
  assert.ok(
    state.ball.y + state.ball.r <= PADDLE_Y + 1e-6,
    'the ball must exit through the top of the paddle',
  );
});

test('D6b: a ball that has NOT reached the paddle yet must not bounce', () => {
  const state = createState(1);
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 13.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.05); // bottom goes 434 → 447, still above the paddle top 448
  assert.equal(Math.sign(state.ball.vy), DOWN, 'no contact yet: the ball keeps descending');
});

test('D7: a center hit on the paddle keeps a playable exit angle and the level speed', () => {
  const state = createState(1);
  const centerX = state.paddle.x + state.paddle.w / 2;
  state.ball = { x: centerX, y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.01); // bottom 447.5 → 450.1, inside the paddle zone
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball must bounce up');
  assert.ok(
    Math.abs(state.ball.vx) >= 0.15 * 260,
    `vx must not be zero at the exact center (got ${state.ball.vx})`,
  );
  assert.ok(
    Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - 260) <= 1e-6,
    'speed after the bounce must be the level speed',
  );
});

test('D8: an edge hit on the paddle preserves the level speed (no speed-up)', () => {
  const state = createState(1);
  const centerX = state.paddle.x + state.paddle.w / 2;
  state.ball = { x: centerX + 0.8 * (state.paddle.w / 2), y: PADDLE_Y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: 260 };
  step(state, 0.01); // hit = 0.8
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball must bounce up');
  assert.ok(
    Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - 260) <= 1e-6,
    `speed must be 260 after the paddle bounce (got ${Math.hypot(state.ball.vx, state.ball.vy).toFixed(2)})`,
  );
});

